        CPU     Z8601
        ASSUME  RP:0

; Working register aliases (synthesis code)
PORT0_DAC       EQU     R0      ; Port 0 DAC
PORT1           EQU     R1      ; Port 1 readback (pitch envelope from master COP)
PORT2           EQU     R2      ; Port 2 readback (bus state: bit 2=RARC)
PORT3           EQU     R3      ; Port 3 readback (EXSLA bits 2:1, ECLK bit 3)
ZERO            EQU     R4      ; always 0 (cleared at synthesis_loop_entry)
MICRO_OP        EQU     R5      ; current micro-op dispatch address (IRQ4 target)
TIMER_LOAD      EQU     R6      ; timer reload value (written to T0 by IRQ1)
PHASE           EQU     R7      ; waveform phase accumulator / table index
ACC_HI          EQU     R8      ; accumulator high byte (frequency deviation)
ACC_LO          EQU     R9      ; accumulator low byte
WAVE_R14        EQU     R14     ; frequency step / phase increment
WAVE_R15        EQU     R15     ; previous waveform sample (interpolation)

; Memory-mapped register aliases (absolute addresses)
MODE            EQU     10h     ; mode register (from slave_ram[$FA])
LFSR_VIB_STATE  EQU     11h     ; LFSR high byte / vibrato running state
PITCH_HI        EQU     12h     ; pitch coeff high: [7:6]=EXSLA [3:0]=coeff.hi (slave_ram[$FC] + EXSLA from Port 3)
PITCH_LO        EQU     13h     ; pitch coeff low = coeff.lo (from slave_ram[$FD])
ACC2_HI         EQU     14h     ; secondary accumulator high (NOT R14!)
ACC2_LO         EQU     15h     ; secondary accumulator low (NOT R15!)
ACC3_HI         EQU     16h     ; tertiary accumulator high
ACC3_LO         EQU     17h     ; tertiary accumulator low
LOOP1_CTR       EQU     18h     ; primary loop counter
LOOP2_CTR       EQU     19h     ; secondary loop counter
PITCH_ENV       EQU     1Ah     ; pitch envelope (from Master, read via Port 1 from slave ram bus-idle address 0xff)
PROG_CTR        EQU     1Bh     ; micro-program counter (indexes $1D-$3C)
BLOCK_CTR       EQU     1Ch     ; block/phase counter (LFSR countdown / coeff toggle)
TIMER_VAL       EQU     1Dh     ; timer reload / pitch (set by synthesis_output)
MICRO_OP_NEXT   EQU     1Eh     ; micro-op chain address (set by synthesis_output)


; === Interrupt vector table (6 vectors × 2 bytes) ===
        ORG     0000h
        DW      023Ah      ; IRQ0/P3.2    → init_full
        DW      0EBEh      ; IRQ1/P3.3    → irq1_handler
        DW      023Ah      ; IRQ2/P3.1    → init_full
        DW      02E0h      ; IRQ3/P3.0    → irq3_handler
        DW      000Fh      ; IRQ4/T0      → irq4_handler
        DW      023Ah      ; IRQ5/T1      → init_full

        ORG     000Ch

; ============================================================
; === RESET ENTRY ($000C) ===
; ============================================================
        ORG     000Ch
reset_entry:
        JP      init_full

; ============================================================
; === IRQ4 — Phase Accumulator + Micro-Op Dispatch ($000F) ===
; ============================================================
        ORG     000Fh
irq4_handler:
; IRQ4 handler: fractional timer dither + micro-op dispatch.
; SPH holds an 8-bit dither pattern (from pitch_output ROM[$0232] table).
; Each IRQ4: rotate pattern left, carry adds 0 or 1 to timer reload.
; This dithers the sample rate by ±1 timer tick, giving 3 bits of
; sub-sample pitch resolution (8 dither patterns = 0/8 to 7/8 fractional).
        RL      0FEh                            ; 0FE=SPH (phase accumulator high)
        ADC     TIMER_LOAD, ZERO                ; R6 += carry (0 or 1) — dithered timer value
        LD      0F4h, TIMER_LOAD                ; 0F4=T0 (timer 0 counter)  ; reload T0 with dithered value
        LD      TIMER_LOAD, TIMER_VAL           ; restore R6 = base timer value from TIMER_VAL (reg[$1D])
        JP      @RR4                            ; dispatch to micro-op at address R4:R5 (R4=ZERO=$00)

; ============================================================
; === Micro-op: Init/silence ($19). Output $80 (center), R7=$40, R5=reg[$1E] ($0019) ===
; ============================================================
        ORG     0019h
micro_silence:
        LD      PORT0_DAC, #80h
        LD      MICRO_OP, MICRO_OP_NEXT
        LD      PHASE, #00h
        IRET

; ============================================================
; === Micro-op: 8× oversample step 1/8 ($20). OR PHASE,#$40 for @R7 indirect access ($0020) ===
; ============================================================
        ORG     0020h
micro_8x_step1:
; 8x oversampled linear scan (Mode A sub 0-5). Lowest pitch range.
; 8 IRQ4 steps per single phase advance. T=$80.
; All 8 steps output interpolated samples. Phase advances once (step 7).
; R14/R15 = working accumulators (read+written by chain).
; Chain: $20->$2C->$37->$44->$51->$5E->$6A->$76->(reg[$1E]=$20).
