        LD      MICRO_OP, #2Ch
        OR      PHASE, #40h
        ADD     WAVE_R15, WAVE_R14
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 8× oversample step 2/8 ($2C). ADD R14,@R7 ($002C) ===
; ============================================================
        ORG     002Ch
micro_8x_step2:
