        LD      MICRO_OP, #37h
        LD      WAVE_R15, WAVE_R14
        ADD     WAVE_R15, @PHASE
        RRC     WAVE_R15
        IRET

; ============================================================
; === Micro-op: 8× oversample step 3/8 ($37). INC R7, lookup @R7 fwd ($0037) ===
; ============================================================
        ORG     0037h
micro_8x_step3:
        LD      PORT0_DAC, WAVE_R14
        LD      MICRO_OP, #44h
        INC     PHASE
        JR      MI, .micro_lookup_overflow
        LD      WAVE_R14, @PHASE
        IRET
.micro_lookup_overflow:                                ; 1 refs
        LD      WAVE_R14, 40h
        IRET

; ============================================================
; === Micro-op: 8× oversample step 4/8 ($44). DEC R7, lookup @R7 bwd ($0044) ===
; ============================================================
        ORG     0044h
micro_8x_step4:
        LD      PORT0_DAC, WAVE_R15
        LD      MICRO_OP, #51h
        DEC     PHASE
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        LD      WAVE_R15, WAVE_R14
        IRET

; ============================================================
; === Micro-op: 8× oversample step 5/8 ($51). Double add @R7 ($0051) ===
; ============================================================
        ORG     0051h
micro_8x_step5:
        LD      PORT0_DAC, @PHASE
        LD      MICRO_OP, #5Eh
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        ADD     WAVE_R14, @PHASE
        RRC     WAVE_R14
        IRET

; ============================================================
; === Micro-op: 8× oversample step 6/8 ($5E). Accumulate + INC R7 ($005E) ===
; ============================================================
        ORG     005Eh
