        AND     ACC3_LO, #0F0h
        INC     PROG_CTR
        LD      ACC3_HI, @PROG_CTR
        JR      interpreter_reentry

; ============================================================
; === CD=imm ($x3) — load immediate to R14:R15 ($05D7) ===
; ============================================================
        ORG     05D7h
op_load_1415:
        LD      ACC2_LO, @PROG_CTR
        AND     ACC2_LO, #0F0h
        INC     PROG_CTR
        LD      ACC2_HI, @PROG_CTR
        JR      interpreter_reentry

; ============================================================
; === ENV=AB ($44) — copy R16:R17 → R8:R9 ($05E4) ===
; ============================================================
        ORG     05E4h
op_copy_1617_to_r8r9:
        LD      ACC_LO, ACC3_LO
        LD      ACC_HI, ACC3_HI
        JP      finalize_output.entry

; ============================================================
; === ENV=CD ($48) — copy R14:R15 → R8:R9 ($05EB) ===
; ============================================================
        ORG     05EBh
op_copy_1415_to_r8r9:
        LD      ACC_LO, ACC2_LO
        LD      ACC_HI, ACC2_HI
        JP      finalize_output.entry

; ============================================================
; === AB=ENV ($54) — copy R8:R9 → R16:R17 ($05F2) ===
; ============================================================
        ORG     05F2h
op_store_r8r9_to_1617:
        LD      ACC3_LO, ACC_LO
        LD      ACC3_HI, ACC_HI
        JR      interpreter_reentry

; ============================================================
; === AB=CD ($4C) — copy R14:R15 → R16:R17 ($05F8) ===
; ============================================================
        ORG     05F8h
op_copy_1415_to_1617:
        LD      ACC3_LO, ACC2_LO
        LD      ACC3_HI, ACC2_HI
        JR      interpreter_reentry

; ============================================================
; === CD=ENV ($58) — copy R8:R9 → R14:R15 ($0600) ===
; ============================================================
        ORG     0600h
op_store_r8r9_to_1415:
        LD      ACC2_LO, ACC_LO
        LD      ACC2_HI, ACC_HI
        JR      interpreter_reentry

; ============================================================
; === CD=AB ($5C) — copy R16:R17 → R14:R15 ($0606) ===
; ============================================================
        ORG     0606h
op_copy_1617_to_1415:
        LD      ACC2_LO, ACC3_LO
        LD      ACC2_HI, ACC3_HI
        JP      interpreter_reentry

; ============================================================
; === ENV MEM ($A4) — register pair indirect op on R8:R9 ($060F) ===
; ============================================================
        ORG     060Fh
op_regpair_op_08:
        LD      R12, #08h
        JR      regpair_dispatch_entry

; ============================================================
; === AB MEM ($A8) — register pair indirect op on R16:R17 ($0613) ===
; ============================================================
        ORG     0613h
op_regpair_op_16:
        LD      R12, #16h
        JR      regpair_dispatch_entry

; ============================================================
; === CD MEM ($AC) — register pair indirect op on R14:R15 ($0617) ===
; ============================================================
        ORG     0617h
op_regpair_op_14:
        LD      R12, #14h
regpair_dispatch_entry:                                ; 2 refs
        INC     PROG_CTR
        LD      R10, @PROG_CTR
        AND     R10, #3Fh
        CP      R10, #30h
        JR      C, .L_0644
        TCM     @PROG_CTR, #40h
        JP      Z, interpreter_reentry
        SUB     R10, #30h
        TCM     @PROG_CTR, #80h
        JR      Z, .L_063C
        CLR     @R12
        LD      01h(R12), R10
        JP      .regpair_exit
.L_063C:                                ; called from: regpair_dispatch_entry($0632)
        LD      @R12, R10
        LD      01h(R12), ZERO
        JP      .regpair_exit
.L_0644:                                ; called from: regpair_dispatch_entry($0624)
        ADD     R10, #1Dh
        TCM     @PROG_CTR, #40h
        JR      Z, .L_0664
        LD      R13, @R10
        LD      @R12, R13
        TCM     @PROG_CTR, #80h
        JR      Z, .L_065E
        LD      R13, 01h(R10)
        LD      01h(R12), R13
        JP      .regpair_exit
.L_065E:                                ; called from: .L_0644($0653)
        LD      01h(R12), ZERO
        JP      .regpair_exit
.L_0664:                                ; called from: .L_0644($064A)
        LD      R13, @R12
        LD      @R10, R13
        TCM     @PROG_CTR, #80h
        JP      Z, .regpair_exit
        LD      R13, 01h(R12)
        LD      01h(R10), R13
        JP      .regpair_exit
.regpair_exit:                                ; 6 refs
        CP      R12, #10h
        JP      C, finalize_output.entry
        JP      interpreter_reentry

; ============================================================
; === ENV+=imm ($x5) — add immediate to R8:R9 ($0680) ===
; ============================================================
        ORG     0680h
op_add_imm_to_r8r9:
        LD      R10, @PROG_CTR
        AND     R10, #0F0h
        ADD     ACC_LO, R10
        INC     PROG_CTR
        ADC     ACC_HI, @PROG_CTR
        JP      finalize_output.entry

; ============================================================
; === AB+=imm ($x6) — add immediate to R16:R17 ($0690) ===
; ============================================================
        ORG     0690h
op_add_imm_to_1617:
        LD      R10, @PROG_CTR
        AND     R10, #0F0h
        ADD     ACC3_LO, R10
        INC     PROG_CTR
        ADC     ACC3_HI, @PROG_CTR
        JP      interpreter_reentry

; ============================================================
; === CD+=imm ($x7) — add immediate to R14:R15 ($06A1) ===
; ============================================================
        ORG     06A1h
op_add_imm_to_1415:
        LD      R10, @PROG_CTR
