        JP      interpreter_reentry

; ============================================================
; === ENV+=AB ($64) — add R16:R17 to R8:R9 ($06B2) ===
; ============================================================
        ORG     06B2h
op_add_1617_to_r8r9:
        ADD     ACC_LO, ACC3_LO
        ADC     ACC_HI, ACC3_HI
        JP      finalize_output.entry

; ============================================================
; === ENV+=CD sat ($68) — add R14:R15 to R8:R9, saturate at $FFFF ($06BB) ===
; ============================================================
        ORG     06BBh
op_add_1415_to_r8r9_sat:
        ADD     ACC_LO, ACC2_LO
        ADC     ACC_HI, ACC2_HI
        JP      NC, finalize_output.entry
