        LD      ACC_HI, #0FFh
        JP      finalize_output.entry

; ============================================================
; === AB+=ENV ($74) — add R8:R9 to R16:R17 ($06CB) ===
; ============================================================
        ORG     06CBh
op_add_r8r9_to_1617:
        ADD     ACC3_LO, ACC_LO
        ADC     ACC3_HI, ACC_HI
        JP      interpreter_reentry

; ============================================================
; === AB+=CD ($6C) — add R14:R15 to R16:R17 ($06D4) ===
; ============================================================
        ORG     06D4h
op_add_1415_to_1617:
        ADD     ACC3_LO, ACC2_LO
        ADC     ACC3_HI, ACC2_HI
        JP      interpreter_reentry

; ============================================================
; === CD+=ENV ($78) — add R8:R9 to R14:R15 ($06DD) ===
; ============================================================
        ORG     06DDh
op_add_r8r9_to_1415:
        ADD     ACC2_LO, ACC_LO
        ADC     ACC2_HI, ACC_HI
        JP      interpreter_reentry

; ============================================================
; === CD+=AB ($7C) — add R16:R17 to R14:R15 ($06E6) ===
; ============================================================
        ORG     06E6h
op_add_1617_to_1415:
        ADD     ACC2_LO, ACC3_LO
        ADC     ACC2_HI, ACC3_HI
        JP      interpreter_reentry

; ============================================================
; === ENV-=AB ($84) — subtract R16:R17 from R8:R9 ($06EF) ===
; ============================================================
        ORG     06EFh
op_sub_1617_from_r8r9:
        SUB     ACC_LO, ACC3_LO
        SBC     ACC_HI, ACC3_HI
        JP      finalize_output.entry

; ============================================================
; === ENV-=CD ($88) — subtract R14:R15 from R8:R9, floor at 0 ($06F8) ===
; ============================================================
        ORG     06F8h
op_sub_1415_from_r8r9:
        SUB     ACC_LO, ACC2_LO
        SBC     ACC_HI, ACC2_HI
        JP      NC, finalize_output.entry
        CLR     ACC_LO
        CLR     ACC_HI
        JP      finalize_output.entry

; ============================================================
; === AB-=ENV ($94) — subtract R8:R9 from R16:R17 ($0708) ===
; ============================================================
        ORG     0708h
op_sub_r8r9_from_1617:
        SUB     ACC3_LO, ACC_LO
        SBC     ACC3_HI, ACC_HI
        JP      interpreter_reentry

; ============================================================
; === AB-=CD ($8C) — subtract R14:R15 from R16:R17 ($0711) ===
; ============================================================
        ORG     0711h
op_sub_1415_from_1617:
        SUB     ACC3_LO, ACC2_LO
        SBC     ACC3_HI, ACC2_HI
        JP      interpreter_reentry

; ============================================================
; === CD-=ENV ($98) — subtract R8:R9 from R14:R15 ($071A) ===
