        ORG     071Ah
op_sub_r8r9_from_1415:
        SUB     ACC2_LO, ACC_LO
        SBC     ACC2_HI, ACC_HI
        JP      interpreter_reentry

; ============================================================
; === CD-=AB ($9C) — subtract R16:R17 from R14:R15 ($0723) ===
; ============================================================
        ORG     0723h
op_sub_1617_from_1415:
        SUB     ACC2_LO, ACC3_LO
        SBC     ACC2_HI, ACC3_HI
        JP      interpreter_reentry

; ============================================================
; === ENV*=0.(-A) ($F0) — negate R16_HI then multiply ENV ($072C) ===
; ============================================================
        ORG     072Ch
op_neg16_multiply:
        LD      R12, ACC3_HI
        COM     R12
        INC     R12
        JR      NZ, multiply_8x16_r8r9
        JP      finalize_output.entry

; ============================================================
; === ENV*=0.(-C) ($F4) — negate R14_HI then multiply ENV ($0736) ===
; ============================================================
        ORG     0736h
op_neg14_multiply:
        LD      R12, ACC2_HI
        COM     R12
        INC     R12
        JR      NZ, multiply_8x16_r8r9
        JP      finalize_output.entry

; ============================================================
; === ENV*=0.A ($D0) — multiply ENV by R16_HI (fractional) ($0740) ===
; ============================================================
        ORG     0740h
op_mul_by_16:
        LD      R12, ACC3_HI
        JR      multiply_8x16_r8r9

; ============================================================
; === ENV*=0.C ($D4) — multiply ENV by R14_HI (fractional) ($0744) ===
; ============================================================
        ORG     0744h
op_mul_by_11:
        LD      R12, LFSR_VIB_STATE
        JR      multiply_8x16_r8r9

; ============================================================
; === ENV*=0.imm ($B4) — multiply ENV by immediate (fractional) ($0748) ===
; ============================================================
        ORG     0748h
op_mul_by_imm:
        INC     PROG_CTR
        LD      R12, @PROG_CTR

; ============================================================
; === 8x16 multiply variants ($074D) ===
; ============================================================
        ORG     074Dh
multiply_8x16_r8r9:                                ; 5 refs
        LD      R13, #08h
        CLR     R10
        CLR     R11
.L_0753:                                ; called from: .L_075B($075F)
        RR      R12
        JR      NC, .L_075B
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.L_075B:                                ; called from: .L_0753($0755)
        RRC     R10
        RRC     R11
        DJNZ    R13, .L_0753
        ADC     R11, ZERO
        ADC     R10, ZERO
        LD      ACC_LO, R11
        LD      ACC_HI, R10
        JP      finalize_output.entry

; ============================================================
; === AB*=0.(-C) ($F8) — negate R14_HI, multiply into R16:R17 ($076C) ===
; ============================================================
        ORG     076Ch
op_neg14_mul_to_1617:
        LD      R12, ACC2_HI                    ; R12 = ACC2_HI (secondary accumulator high)
        COM     R12                             ; negate: two's complement step 1
        INC     R12                             ; negate: two's complement step 2 (Z=1 if original was $00)
        JR      NZ, multiply_to_1617            ; non-zero → multiply with negated coefficient
        JP      interpreter_reentry             ; PATCHED: JP GT (never true when Z=1) → fall through. ORIGINAL: JP (unconditional) → dead code
.neg14_zero_fallback:
        LD      R12, ACC_HI                     ; FIXME UNREACHABLE without patch: use ACC_HI as fallback coefficient when source is zero
        JR      multiply_to_1617                ; → multiply with ACC_HI instead of negated ACC2_HI

; ============================================================
; === AB*=0.C ($D8) — multiply R16:R17 by R14_HI (fractional) ($077A) ===
; ============================================================
        ORG     077Ah
op_mul14_to_1617:
        LD      R12, ACC2_HI
        JR      multiply_to_1617

; ============================================================
; === AB*=0.imm ($B8) — multiply R16:R17 by immediate (fractional) ($077E) ===
; ============================================================
        ORG     077Eh
op_mulimm_to_1617:
        INC     PROG_CTR
        LD      R12, @PROG_CTR
