; ============================================================
; === STDLINEAR ($A0) — 6-stage linear envelope, 21-byte instruction ($0A7B) ===
; ============================================================
        ORG     0A7Bh
op_stdlinear:
; STDLINEAR: 6-stage linear envelope with final hold value.
; Opcode $A0, 21 bytes total. Each ECLK tick, adds a step to ACC
; for the current stage's duration, then advances to the next stage.
; 
; Instruction layout (21 bytes, PROG_CTR points to byte[0] = $A0):
;   byte[0]:     $A0 opcode
;   byte[1-3]:   stage 1 {step_hi, step_lo, duration}
;   byte[4-6]:   stage 2 {step_hi, step_lo, duration}
;   byte[7-9]:   stage 3 {step_hi, step_lo, duration}
;   byte[10-12]: stage 4 {step_hi, step_lo, duration}
;   byte[13-15]: stage 5 {step_hi, step_lo, duration}
;   byte[16-18]: stage 6 {step_hi, step_lo, duration}
;   byte[19-20]: final value {acc_hi, acc_lo} (loaded when all stages complete)
; 
; Per-stage execution (each ECLK tick):
;   1. R10 = PROG_CTR + BLOCK_CTR → points to current stage's duration byte
;   2. If LOOP1_CTR > 0: DEC LOOP1_CTR, ACC += step (from bytes before duration)
;   3. If LOOP1_CTR == 0: load duration from @R10, check for stage advance
;   4. If LOOP1_CTR < 0 (bit 7 set = $80): sustain — hold forever at multiply
; 
; Stage advance: BLOCK_CTR += 3, advance to next stage. If BLOCK_CTR > $12 (18)
;   → all 6 stages done: load final ACC from bytes[19:20], clear counters,
;   advance PROG_CTR past 21 bytes, continue to next opcode.
; 
; BLOCK_CTR persists between ECLK ticks (tracks current stage).
; LOOP1_CTR persists (counts down within a stage).
; Both are cleared by update_path on each RAUD — so stages restart from 1.
        LD      R10, PROG_CTR
        CP      BLOCK_CTR, ZERO                 ; BLOCK_CTR == 0? (first call or after RAUD reset)
        JR      NZ, .stage_resume               ; not first → use existing BLOCK_CTR (resume current stage)
        LD      BLOCK_CTR, #03h                 ; first call: BLOCK_CTR = 3 (point to stage 1 duration)
.stage_resume:                                ; 1 refs
        ADD     R10, BLOCK_CTR                  ; R10 = PROG_CTR + BLOCK_CTR → current stage's duration byte
        CP      LOOP1_CTR, ZERO                 ; LOOP1_CTR == 0? (need to load new stage?)
        JR      NZ, .check_sustain              ; LOOP1_CTR != 0 → check sign and continue current stage
.load_duration:                                ; 1 refs
        LD      LOOP1_CTR, @R10                 ; load duration: LOOP1_CTR = @R10 (stage's duration byte)
        CP      LOOP1_CTR, ZERO
        JR      .check_done                     ; jump to zero-check (skip the MI/DEC path)
.check_sustain:                                ; 1 refs
        JP      MI, finalize_output.multiply    ; LOOP1_CTR < 0 (bit 7 set) → sustain: hold at multiply forever
        DEC     LOOP1_CTR                       ; DEC LOOP1_CTR (count down one ECLK tick)
.check_done:                                ; 1 refs
        JR      Z, .advance_stage               ; LOOP1_CTR == 0 after DEC or load? → advance to next stage
        DEC     R10                             ; DEC R10 → points to step_lo
        ADD     ACC_LO, @R10                    ; ACC_LO += step_lo
        DEC     R10                             ; DEC R10 → points to step_hi
        ADC     ACC_HI, @R10                    ; ACC_HI += step_hi (with carry from step_lo add)
        JP      finalize_output.multiply        ; → multiply with updated ACC
.advance_stage:                                ; 1 refs
        ADD     BLOCK_CTR, #03h                 ; advance to next stage: BLOCK_CTR += 3, R10 += 3
        ADD     R10, #03h
        CP      BLOCK_CTR, #12h                 ; BLOCK_CTR <= $12 (18)? → more stages remain, loop back
        JR      ULE, .load_duration
.all_stages_done:
        LD      PROG_CTR, R10                   ; all 6 stages done: PROG_CTR = R10 (advance past 21-byte instruction)
        DEC     R10                             ; load final ACC value from bytes[19:20]
        LD      ACC_LO, @R10
        DEC     R10
        LD      ACC_HI, @R10
        CLR     BLOCK_CTR                       ; clear BLOCK_CTR and LOOP1_CTR (envelope complete)
        CLR     LOOP1_CTR
        JP      finalize_output.multiply        ; → multiply with final ACC value

; ============================================================
; === VIBRATO1 ($80) — alternating coefficient multiply, 4-byte ($0AC3) ===
; ============================================================
        ORG     0AC3h
op_vibrato1:
; Vibrato 1: alternating coefficient multiply. Opcode $80, 4-byte.
; Layout: {opcode, coeff1, coeff2, loop_count}
; Uses BLOCK_CTR (reg[$1C]) as toggle between two coefficients.
;   $1C==0: reload loop counter from FREQ[3], toggle $1C
;   $1C!=0: DEC counter, multiply by coeff1 or coeff2 based on toggle
; Alternates R8:R9 *= coeff1 and R8:R9 += coeff2 × R8:R9.
; Creates vibrato by periodically scaling ACC between two rates.
        TCM     MODE, #40h
        JP      Z, finalize_output.multiply     ; MODE bit 6 clear → skip vibrato, go to finalize_output.multiply
        LD      R10, PROG_CTR
        CP      LOOP1_CTR, ZERO                 ; LOOP1_CTR (reg[$18]) == 0?
        JR      NZ, .L_0ADC                     ; non-zero → already running, go to coeff_step
        COM     BLOCK_CTR                       ; toggle BLOCK_CTR (alternate coefficient selection)
        LD      R11, 03h(R10)                   ; reload loop counter from FREQ[3]
        LD      LOOP1_CTR, R11
        CP      R11, ZERO                       ; counter == 0 → no iterations, skip to finalize
        JP      Z, finalize_output.multiply
.L_0ADC:                                ; called from: op_vibrato1($0ACE)
        DEC     PROG_CTR                        ; DEC PROG_CTR (back up to re-read opcode on next pass)
        DEC     LOOP1_CTR                       ; DEC LOOP1_CTR
        CP      BLOCK_CTR, ZERO                 ; BLOCK_CTR toggle state? 0 = use coeff2, else = use coeff1
        JR      Z, .vib1_use_coeff2
        LD      R12, 01h(R10)                   ; R12 = FREQ[1] (coefficient 1)
        JP      multiply_8x16_r8r9              ; → multiply_8x16_r8r9 (R8:R9 *= R12)
.vib1_use_coeff2:                                ; 1 refs
        LD      R12, 02h(R10)                   ; R12 = FREQ[2] (coefficient 2)
        JP      multiply_acc_r8r9               ; → multiply_acc_r8r9 (R8:R9 += R12 × R8:R9)

; ============================================================
; === VIBRATO2 ($90) — sine phase modulation, 4-byte ($0AF1) ===
; ============================================================
        ORG     0AF1h
op_vibrato2:
; Vibrato 2: sine-wave phase modulation. Opcode $90, 4-byte.
; Layout: {opcode, saved_R9, phase_increment, freq_param}
; Phase accumulator in reg[$14:$15], starts at $4000 (quarter-wave).
; Each iteration: phase += increment, sine ROM lookup at $0FC0-$0FFF,
; multiply sine × freq_param, sign-correct by quadrant, add to R8:R9.
; Uses reg[$16:$17] as frequency, reg[$18:$19] as phase step.
; Creates periodic pitch modulation (vibrato/tremolo).
        TCM     MODE, #40h
        JP      Z, finalize_output.multiply     ; MODE bit 6 clear → skip vibrato
        LD      R10, PROG_CTR
        CP      BLOCK_CTR, ZERO                 ; BLOCK_CTR == 0? (first call)
        JR      NZ, .vib2_iteration             ; non-zero → already initialized, go to iteration
        INC     R10                             ; first call: load loop count from FREQ[1]
        LD      BLOCK_CTR, @R10
        CP      BLOCK_CTR, ZERO
        JP      Z, finalize_output.multiply     ; loop count == 0 → skip
.vib2_save_r9:
        LD      @R10, ACC_LO                    ; save R9 to FREQ[1] (overwrite loop count with ACC_LO)
        LD      LFSR_VIB_STATE, ACC_HI          ; save R8 to LFSR_VIB_STATE (reg[$11])
        INC     R10
        LD      LOOP2_CTR, @R10                 ; reg[$19] = FREQ[2] (phase increment)
        CLR     LOOP1_CTR
        INC     R10                             ; reg[$17] = FREQ[3] (frequency param)
        LD      ACC3_LO, @R10
        CLR     ACC3_HI                         ; phase accumulator = $4000 (quarter-wave start)
        LD      ACC2_LO, #00h
        LD      ACC2_HI, #40h
        JR      .vib2_sine_lookup
.vib2_iteration:                                ; 1 refs
        CP      BLOCK_CTR, #01h                 ; DEC loop counter
        JR      Z, .vib2_last_iter
        DEC     BLOCK_CTR
        ADD     R10, #02h                       ; phase += increment
        ADD     LOOP2_CTR, @R10
        ADC     LOOP1_CTR, ZERO
        INC     R10
        ADD     ACC3_LO, @R10                   ; freq += param
        ADC     ACC3_HI, ZERO
.vib2_last_iter:                                ; 1 refs
        ADD     ACC2_LO, LOOP2_CTR              ; phase_acc += phase_step
        ADC     ACC2_HI, LOOP1_CTR
.vib2_sine_lookup:                                ; 1 refs
        LD      R13, ACC2_HI                    ; R13 = phase high byte (quadrant selector)
        TCM     ACC2_HI, #40h                   ; test quadrant bit 6
        JR      NZ, .vib2_no_negate             ; quadrant 2 or 4: negate R13 (COM+INC)
        COM     R13
        INC     R13
.vib2_no_negate:                                ; 1 refs
        AND     R13, #7Fh                       ; mask to 0-127 (half-wave index)
        JR      Z, .vib2_clr_r8                 ; zero sine → skip multiply
        ADD     R13, #0BFh                      ; index into sine ROM table at $0FC0-$0FFF
        LD      R12, #0Fh                       ; R12:R13 = $0F:index → ROM lookup
        LDC     R13, @RR12                      ; R13 = sine table value
        LD      R12, #08h                       ; 8x8 multiply: sine × reg[$16:$17]
        CLR     ACC_HI
        CLR     ACC_LO
.L_0B59:                                ; called from: .L_0B63($0B67)
        RR      R13
        JR      NC, .L_0B63
        ADD     ACC_LO, ACC3_LO
        ADC     ACC_HI, ACC3_HI
.L_0B63:                                ; called from: .L_0B59($0B5B)
        RRC     ACC_HI
        RRC     ACC_LO
        DJNZ    R12, .L_0B59
        RCF
        RRC     ACC_HI
        RRC     ACC_LO
        SRA     ACC_HI
        RRC     ACC_LO
        SRA     ACC_HI
        RRC     ACC_LO
        TCM     ACC2_HI, #80h                   ; quadrant 3 or 4: negate result (COM+INCW)
        JR      NZ, .vib2_exit
        COM     ACC_HI
        COM     ACC_LO
        INCW    RR8
.vib2_exit:                                ; 2 refs
        INC     PROG_CTR                        ; add saved ACC offset: R8:R9 += saved values
        ADD     ACC_LO, @PROG_CTR
        ADC     ACC_HI, LFSR_VIB_STATE
        DEC     PROG_CTR
        JP      finalize_output.multiply        ; → finalize_output.multiply
.vib2_clr_r8:                                ; 1 refs
        CLR     ACC_HI                          ; zero sine: CLR R8:R9, then add saved offset
        CLR     ACC_LO
        JR      .vib2_exit

; ============================================================
; === NOISE ($10) — 16-bit Galois LFSR pitch modulation, 4-byte ($0B94) ===
; ============================================================
        ORG     0B94h
op_lfsr_noise:
; op_lfsr_noise: 16-bit Galois LFSR pitch modulation
; Micro-program opcode $10, 4-byte instruction: {opcode, running_state, coefficient, counter/lfsr_low}
; Three paths based on BLOCK_CTR (reg[$1C]):
;   counter==0: reload from FREQ[3], do short LFSR, advance if zero
;   counter>0:  decrement, 8-bit LFSR step (high byte only, XOR $1D)
;   counter<0:  full 16-bit LFSR step + pitch envelope S&H from COP
; Exit: differenced noise x coefficient -> R8:R9 -> finalize_output.multiply
        LD      R10, PROG_CTR
        CP      BLOCK_CTR, ZERO                 ; block counter == 0?
        JR      NZ, .counter_nonzero            ; non-zero → check sign
        LD      R11, 03h(R10)                   ; reload block counter from FREQ[3] (LFSR low byte / reload value)
        LD      BLOCK_CTR, R11                  ; block counter = reload value
        CP      BLOCK_CTR, ZERO                 ; still zero after reload?
        JR      .check_zero
.counter_nonzero:                                ; 1 refs
        JR      MI, .full_lfsr_step             ; negative → full 16-bit LFSR step
        DEC     BLOCK_CTR                       ; positive → just decrement counter
.check_zero:                                ; 1 refs
        JR      NZ, .short_lfsr                 ; non-zero → 8-bit LFSR step (short path)
        CLR     BLOCK_CTR                       ; counter exhausted → clear and advance past 4-byte instruction
        ADD     PROG_CTR, #04h                  ; advance micro-program counter by 4
        JP      micro_program_interpreter       ; back to interpreter
.full_lfsr_step:                                ; 1 refs
        ADD     R10, #03h                       ; point to LFSR low byte (FREQ[3])
        RLC     @R10                            ; rotate low byte left (16-bit LFSR shift)
        RLC     LFSR_VIB_STATE                  ; rotate high byte left (carry chain from low)
        JR      NC, .no_feedback                ; carry set → apply feedback polynomial
        XOR     @R10, #87h                      ; XOR low byte with $87 (polynomial feedback)
        XOR     LFSR_VIB_STATE, #1Dh            ; XOR high byte with $1D (polynomial = $1D87)
.no_feedback:                                ; 1 refs
        SUB     R10, #03h                       ; restore R10 to instruction base
        OR      0FAh, #02h                      ; 0FA=IRQ (interrupt request)  ; set IRQ1 pending (software flag) → forces synthesis_output on next reentry poll
        TCM     PORT2, #04h                     ; check bus state (RARC) for envelope read
        JR      NZ, .coeff_exit                 ; bus busy → skip envelope S&H
        LD      R12, PORT3                      ; R12 = Port 3 (EXSLA routing bits)
        LD      R13, PORT1                      ; R13 = Port 1 (pitch envelope from master COP)
        TCM     PORT2, #04h                     ; re-check bus (may have changed during read)
        JR      NZ, .coeff_exit                 ; bus changed → discard
        TCM     MODE, #80h                      ; MODE bit 7: pitch envelope enable? (same test as update_path/$034C)
        JR      NZ, .coeff_exit                 ; bit 7 CLEAR → no pitch tracking, skip PITCH_ENV/EXSLA update
        LD      PITCH_ENV, R13                  ; reg[$1A] = pitch envelope value (modulation depth)
        SWAP    R12                             ; extract EXSLA routing from Port 3
        RL      R12
        AND     R12, #0C0h
        AND     PITCH_HI, #3Fh                  ; merge EXSLA bits into reg[$12] (coefficient high bits)
        OR      PITCH_HI, R12
        JR      .coeff_exit
.short_lfsr:                                ; 1 refs
        RCF
        RLC     LFSR_VIB_STATE
        JR      NC, .coeff_exit                 ; carry → XOR with $1D (8-bit feedback)
        XOR     LFSR_VIB_STATE, #1Dh
.coeff_exit:                                ; 5 refs
        LD      R11, 02h(R10)                   ; R11 = FREQ[2] (multiply coefficient)
        LD      R12, #08h                       ; 8-bit multiply loop counter
        CLR     R13                             ; clear accumulator
.mul_loop:                                ; 1 refs
        RR      R11                             ; shift coefficient right
        JR      NC, .mul_skip                   ; bit clear → skip add
        ADD     R13, LFSR_VIB_STATE             ; accumulate: R13 += LFSR high byte (reg[$11])
.mul_skip:                                ; 1 refs
        RRC     R13                             ; shift result right
        DJNZ    R12, .mul_loop                  ; loop 8 times
        ADC     R13, ZERO                       ; round up (2x ADC for bias correction)
        ADC     R13, ZERO
        RRC     R11                             ; R11 = coefficient >> 1
        CLR     R12                             ; clear R12 (sign extension)
        SUB     R13, R11                        ; center: product -= coefficient/2 (zero-mean noise)
        SBC     R12, ZERO
        LD      R11, R13                        ; R11 = centered product (new running state)
        INC     R10                             ; point to FREQ[1] (old running state)
        CP      @R10, #00h                      ; sign of old running state?
        JR      MI, .diff_neg                   ; negative → sign-extend subtraction
        SUB     R13, @R10                       ; delta = new - old (positive old, SBC R4=0)
        SBC     R12, ZERO
        JR      .store_state
.diff_neg:                                ; 1 refs
        SUB     R13, @R10                       ; delta = new - old (negative old, SBC #$FF for sign-extend)
        SBC     R12, #0FFh
.store_state:                                ; 1 refs
        LD      @R10, R11                       ; store new running state to FREQ[1]
        RLC     R13                             ; scale delta left 4 times (×16)
        RLC     R12
        RLC     R13
        RLC     R12
        RLC     R13
        RLC     R12
        RLC     R13
        RLC     R12
        AND     R13, #0F0h                      ; mask to upper nibble
        ADD     ACC_LO, R13                     ; R8:R9 += scaled delta (accumulate into ACC)
        ADC     ACC_HI, R12
        JP      finalize_output.multiply        ; → finalize_output.multiply (12×16 multiply with coefficient)

; ============================================================
; === AB=NOISE X=imm ($20) — LFSR step + multiply → R16:R17 ($0C41) ===
; ============================================================
        ORG     0C41h
op_lfsr_mul_1617:
        RCF
        RLC     LFSR_VIB_STATE
        JR      NC, .L_0C49
        XOR     LFSR_VIB_STATE, #1Dh
.L_0C49:                                ; called from: op_lfsr_mul_1617($0C44)
        INC     PROG_CTR
        LD      R10, @PROG_CTR
        CLR     R11
        LD      R12, #08h
        CLR     ACC3_HI
        CLR     ACC3_LO
.L_0C56:                                ; called from: .L_0C60($0C64)
        RR      LFSR_VIB_STATE
        JR      NC, .L_0C60
        ADD     ACC3_LO, R11
        ADC     ACC3_HI, R10
.L_0C60:                                ; called from: .L_0C56($0C58)
        RRC     ACC3_HI
        RRC     ACC3_LO
        DJNZ    R12, .L_0C56
        RRC     R10
        RRC     R11
        SUB     ACC3_LO, R11
        SBC     ACC3_HI, R10
        JP      interpreter_reentry

; ============================================================
; === CD=NOISE X=imm ($30) — LFSR step + multiply → R14:R15 ($0C73) ===
; ============================================================
        ORG     0C73h
op_lfsr_mul_1415:
        RCF
        RLC     LFSR_VIB_STATE
        JR      NC, .L_0C7B
        XOR     LFSR_VIB_STATE, #1Dh
.L_0C7B:                                ; called from: op_lfsr_mul_1415($0C76)
        INC     PROG_CTR
        LD      R10, @PROG_CTR
        CLR     R11
        LD      R12, #08h
        CLR     ACC2_HI
        CLR     ACC2_LO
.L_0C88:                                ; called from: .L_0C92($0C96)
        RR      LFSR_VIB_STATE
        JR      NC, .L_0C92
        ADD     ACC2_LO, R11
        ADC     ACC2_HI, R10
.L_0C92:                                ; called from: .L_0C88($0C8A)
        RRC     ACC2_HI
        RRC     ACC2_LO
        DJNZ    R12, .L_0C88
        RRC     R10
        RRC     R11
        SUB     ACC2_LO, R11
        SBC     ACC2_HI, R10
        JP      interpreter_reentry

; ============================================================
; === ACC library init + 12x12 unsigned multiply + pitch envelope + pitch output ($0CA5) ===
; ============================================================
        ORG     0CA5h
finalize_output:                                ; 1 refs
; ACC initializer — implements mk1 FREQ library programs.
; Called by micro_program_interpreter when PROG_CTR >= $3D.
; 
; How it works: micro_raw[0] (start_offset byte in FREQ block) serves as
; both a program offset AND a library address. synthesis_loop_entry adds $1C
; to PROG_CTR, then interpreter_reentry adds 1 more (total +$1D). When
; start_offset >= $20, the result is >= $3D, routing here instead of executing
; bytecodes. This implements the mk1utils ROM library (mk1envlib.c):
; 
;   start_offset | PROG_CTR after +$1D | ACC set to | mk1utils name
;   $20           | $3D (Z shortcut)    | $0000*     | HALT (no envelope)
;   $22           | $3F                 | $2D00      | ENV=$2CE4; HALT
;   $26           | $43                 | $4000      | ENV=$4000; HALT
;   $2A           | $47                 | $8000      | ENV=$8000; HALT
;   $2E           | $4B                 | $FFFF      | ENV=$FFFF; HALT
;   * $20 takes Z shortcut → ACC stays $0000 from synthesis_loop_entry CLR
; 
; After setting ACC: PROG_CTR reset to $3D = HALT state. All subsequent
; interpreter calls hit the Z shortcut and go directly to multiply.
; 
; Entry: Z flag from 'CP PROG_CTR, #$3D' in micro_program_interpreter.
;   Z set (PROG_CTR == $3D): HALT state → skip init, go to multiply.
;   Z clear (PROG_CTR > $3D): library init → set ACC, reset to $3D.
; 
; For normal programs (start_offset=$02): PROG_CTR = $02 + $1D = $1F,
; below $3D → interpreter fetches opcodes from reg[$1F] normally.
; 
; The LFSR noise handler (op_lfsr_noise) at $0C3E jumps directly to
; finalize_output.multiply, bypassing this path. LFSR voices use real
; programs (offset $02) with explicit LOAD opcodes to set ACC.
        JR      Z, finalize_output.multiply
        CP      PROG_CTR, #43h                  ; which library entry? compare PROG_CTR to thresholds
        JR      UGT, .finalize_sub43_check      ; PROG_CTR > $43 → check upper range ($2A/$2E entries)
        JR      Z, .L_0CB2                      ; PROG_CTR == $43: library $26 (ENV=$4000)
        LD      ACC_HI, #2Dh                    ; PROG_CTR < $43: library $22 (ENV=$2D00 ≈ $2CE4)
        JR      .finalize_check
.L_0CB2:                                ; called from: finalize_output($0CAC)
        LD      ACC_HI, #40h                    ; library $26: ACC = $4000 (quarter range)
        JR      .finalize_check
.finalize_sub43_check:                                ; 1 refs
        CP      PROG_CTR, #4Bh                  ; check if PROG_CTR >= $4B (library $2E)
        JR      NC, .finalize_clamp_max         ; PROG_CTR >= $4B → library $2E (ENV=$FFFF)
        LD      ACC_HI, #80h                    ; library $2A: ACC = $8000 (center — standard for noise voices)
.finalize_check:                                ; 2 refs
        CLR     ACC_LO                          ; clear low byte (ACC = ACC_HI:$00)
        JR      .finalize_reset_counter
.finalize_clamp_max:                                ; 1 refs
        LD      ACC_HI, #0FFh                   ; library $2E: ACC = $FFFF (maximum)
        LD      ACC_LO, #0FFh
.finalize_reset_counter:                                ; 1 refs
        LD      PROG_CTR, #3Dh                  ; PROG_CTR = $3D → HALT state (library program done, just multiply from now on)
        JR      finalize_output.multiply
finalize_output.entry:                                ; 20 refs
        INC     PROG_CTR
finalize_output.multiply:                                ; 12 refs
; 12x12 unsigned fixed-point multiply.
; Formula: R10:R11 = ACC[11:0] * COEFF[11:0] / 2048
; ACC is unsigned 12-bit: {R8[7:0], R9[7:4]} (low nibble of R9 always 0).
; COEFF is 1.11 fixed-point: {PITCH_HI[3:0], PITCH_LO[7:0]}.
;   bit 11 (PITCH_HI bit 3) = integer bit (weight x1.0)
;   bits 10:0 = fractional.  Range: 0.0 to ~2.0. Unity at COEFF=$800.
; PITCH_HI[5:4] = EXSLA staging (not used by multiply).
; PITCH_HI[7:6] = EXSLA bits (used by pitch_apply AFTER multiply).
; 12 unrolled iterations: 8 from PITCH_LO + 4 from PITCH_HI[3:0].
; NOTE: no final RRC after bit 11 iteration -> bit 11 has weight 1.0.
; Carry after bit 11 = genuine overflow (result > 16 bits) -> pitch_overflow.
; With correct ACC base (~$8000), overflow should rarely fire.
        LD      R12, PITCH_HI
        LD      R13, PITCH_LO                   ; R13=PITCH_LO
        CLR     R10                             ; clear result accumulator R10:R11
        CLR     R11
        RR      R13                             ; coeff bit 0 (PITCH_LO bit 0)
        JR      NC, .mul_bit1
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit1:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 1
        JR      NC, .mul_bit2
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit2:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 2
        JR      NC, .mul_bit3
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit3:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 3
        JR      NC, .mul_bit4
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit4:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 4
        JR      NC, .mul_bit5
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit5:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 5
        JR      NC, .mul_bit6
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit6:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 6
        JR      NC, .mul_bit7
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit7:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R13                             ; coeff bit 7 (PITCH_LO bit 7, last of low byte)
        JR      NC, .mul_bit8
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit8:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R12                             ; coeff bit 8 (PITCH_HI bit 0)
        JR      NC, .mul_bit9
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit9:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R12                             ; coeff bit 9
        JR      NC, .mul_bit10
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit10:                                ; 1 refs
        RRC     R10
        RRC     R11
        RR      R12                             ; coeff bit 10
        JR      NC, .mul_bit11
        ADD     R11, ACC_LO
        ADC     R10, ACC_HI
.mul_bit11:                                ; 1 refs
        RRC     R10
        RRC     R11
; Coeff bit 11 = PITCH_HI bit 3 (integer bit, weight 1.0).
; Last iteration: adds ACC at FULL weight (no final RRC shift).
; With bit 11 set: result ≈ ACC × (1 + fraction). Can overflow if ACC is large.
; With bit 11 clear: result = ACC × fraction (< ACC). Never overflows.
; Carry from ADC = genuine overflow (result > 16 bits), NOT a sign test.
; With correct ACC base ($8000 ± noise), overflow should rarely fire.
        RR      R12
        JR      NC, .mul_overflow_check         ; bit 11 clear → skip ADD, carry from previous RRC (not meaningful)
        ADD     R11, ACC_LO                     ; bit 11 set → add ACC at weight 1.0 (result ≈ ACC × (1 + fraction))
        ADC     R10, ACC_HI
.mul_overflow_check:                                ; 1 refs
        JP      C, finalize.pitch_overflow      ; carry = overflow: result > 16 bits → pitch_overflow (halve + re-apply)
finalize.pitch_apply:
        CP      PITCH_ENV, ZERO
        JP      Z, finalize_output.check_underflow_ld_r12_r10; LD R12, R10 - returns to finalize_output.check_underflow
        CLR     R12
        CLR     R13
        RR      PITCH_ENV
        JR      NC, .L_0D75
        ADD     R13, R11
        ADC     R12, R10
.L_0D75:                                ; called from: finalize.pitch_apply($0D6F)
        RRC     R12                             ; skip bit0 envelope direction handled at 0xDD9
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0D81
        ADD     R13, R11
        ADC     R12, R10
.L_0D81:                                ; called from: .L_0D75($0D7B)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0D8D
        ADD     R13, R11
        ADC     R12, R10
.L_0D8D:                                ; called from: .L_0D81($0D87)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0D99
        ADD     R13, R11
        ADC     R12, R10
.L_0D99:                                ; called from: .L_0D8D($0D93)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0DA5
        ADD     R13, R11
        ADC     R12, R10
.L_0DA5:                                ; called from: .L_0D99($0D9F)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0DB1
        ADD     R13, R11
        ADC     R12, R10
.L_0DB1:                                ; called from: .L_0DA5($0DAB)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .mul_exsla_bit0
        ADD     R13, R11
        ADC     R12, R10
.mul_exsla_bit0:                                ; 1 refs
        RRC     R12
        RRC     R13
        TCM     PITCH_HI, #40h
        JR      NZ, .mul_exsla_bit1
        RCF
        RRC     R12
        RRC     R13
.mul_exsla_bit1:                                ; 1 refs
        TCM     PITCH_HI, #80h
        JR      NZ, .modulation_dir_check
        RCF
        RRC     R12
        RRC     R13
        SRA     R12
        RRC     R13
.modulation_dir_check:                                ; 1 refs
        TCM     PITCH_ENV, #01h
        JR      NZ, .L_0DE6
        SBC     R11, R13
        SBC     R10, R12
        LD      R12, R10
        JR      finalize_output.check_underflow
.L_0DE6:                                ; called from: .modulation_dir_check($0DDC)
        ADC     R11, R13
        ADC     R12, R10
        JP      C, finalize_output.overflow_shift; returns to pitch_output
finalize_output.check_underflow:                                ; 2 refs
        LD      R13, MODE
        AND     R13, #0Fh
        CP      R12, #1Eh
        JP      C, finalize_output.underflow_shift; returns to pitch_output[.underflow_shift_entry]
finalize_output.pitch_output:                                ; 6 refs
; Paths from finalize.envelope and finalize.pitch_overflow join herepitch_output: prepare synthesis_output parameters
; Inputs: R12 = multiply result high (magnitude), R11 = low byte
;         R13 = sub mode (from check_underflow/normalize/overflow)
; R11 bits 7:5 select fractional freq dither pattern from ROM table at $0232.
; Dither pattern stored in SPH, rotated each IRQ4 for sub-sample pitch accuracy.
        LD      R10, #02h
        SWAP    R11                             ; extract R11 bits 7:5: SWAP nibbles
        RR      R11                             ; RR: bits 7:5 now at 2:0
        AND     R11, #07h                       ; isolate 3-bit index (0-7)
        ADD     R11, #32h                       ; table base $32 + index
        LDC     R11, @RR10                      ; R11 = ROM[$0232+i] = fractional dither pattern (0-7 of 8 bits set)
finalize_output.pitch_output.underflow_shift_entry:                                ; 1 refs
; 8th RR restores PITCH_ENV to original value after
; 7 RR's in pitch_apply/overflow multiply. Needed when ECLK is
; already pending or bus not free (PITCH_ENV not refreshed from Port 1).
; Also entry from underflow_shift cap (R12=$1E, R11=0 = no dither).
        RR      PITCH_ENV
; Calculate synthesis mode table pointer
; R10 = R12 (save magnitude for synthesis_output pitch calc)
        LD      R10, R12
        LD      R12, MODE
        AND     R12, #30h
        ADD     R13, R12                        ; R13 += mode_offset (\$20=ModeA, \$00=ModeB, \$10=ModeC)
        LD      R12, #01h                       ; R12 = 1 (for R13*3+1 computation)
        ADD     R12, R13                        ; R12 = 1 + (sub + mode_offset)
        RL      R13                             ; R13 = (sub + mode_offset) * 2
        ADD     R13, R12                        ; R13 = (sub+mode_offset)*2 + 1 + (sub+mode_offset) = (sub+mode_offset)*3 + 1
.f2_nyquist_gate:
; Anti-aliasing gate for Mode C ($F2 wrap DDS).
; T byte (param table byte0) is the phase increment (→ R14).
; If T*2 >= R15 (wrap point), the DDS completes a cycle in < 2 ticks
; — above Nyquist. Gate forces silence to prevent aliased noise.
; The frequency envelope can push pitch up until this gate fires,
; acting as an automatic upper-frequency cutoff.
        CP      MICRO_OP_NEXT, #0F2h
        JR      NZ, synthesis_loop_reentry      ; not $F2 → skip gate (only Mode C needs this check)
        LD      R12, #01h                       ; R12 = $01 (ROM high byte for param table at $01xx)
        LDC     R12, @RR12                      ; R12 = ROM[$01:R13] = T byte = phase step for new sub-mode
        RL      R12                             ; RL R12 → T * 2 (phase advance in 2 IRQ4 ticks)
        CP      R12, WAVE_R15                   ; T*2 vs R15: C set if T*2 < R15 (at least 2 samples/cycle)
        JR      C, synthesis_loop_reentry       ; T*2 < R15 → below Nyquist, normal operation
        LD      R13, #2Eh                       ; T*2 >= R15 → above Nyquist! R13=$2E = silence (Mode C sub=15, op=$19)

; ============================================================
; === Synthesis loop re-entry (ECLK poll). R13 = param table index for synthesis_output (byte0 offset). Set by pitch_output or synthesis_pass_done ($0E2A) ===
; ============================================================
        ORG     0E2Ah
synthesis_loop_reentry:                                ; 7 refs
        TCM     0FAh, #02h                      ; 0FA=IRQ (interrupt request)  ; test IRQ bit 1 (ECLK pending from COP or LFSR software set)
        JR      Z, synthesis_output             ; ECLK pending → call synthesis_output
        TCM     PORT2, #04h                     ; bus check: RARC bit 2 clear = bus available
        JR      NZ, synthesis_loop_reentry      ; bus busy → retry
        LD      R12, PORT3                      ; stage 1: read Port 3 for EXSLA bits
        RR      R12                             ; RR: shift EXSLA (bits 2:1) → bits 1:0
        SWAP    R12                             ; SWAP: bits 1:0 → bits 5:4
        AND     R12, #30h                       ; keep only bits 5:4 = EXSLA (staging position)
        AND     PITCH_HI, #0CFh                 ; clear staging area in PITCH_HI (bits 5:4)
        OR      PITCH_HI, R12                   ; merge EXSLA into PITCH_HI bits 5:4 (temporary)
        LD      R12, PORT1                      ; read Port 1 = pitch envelope from master COP
        TCM     PORT2, #04h                     ; re-check bus (may have changed during Port 1 read)
        JR      NZ, synthesis_loop_reentry      ; bus changed → restart (discard both EXSLA and pitch)
        TCM     MODE, #80h                      ; MODE bit 7: pitch envelope enable? (bit 7 CLEAR = no pitch tracking)
        JR      NZ, synthesis_loop_reentry      ; override set → restart (don't update pitch envelope)
        LD      PITCH_ENV, R12                  ; commit: store pitch envelope (bus verified stable)
        LD      R12, PITCH_HI                   ; stage 2: promote EXSLA from bits 5:4 to final bits 7:6
        RL      R12                             ; RL×2: shift bits 5:4 → bits 7:6
        RL      R12
        AND     R12, #0C0h                      ; keep only bits 7:6 = EXSLA (final position)
        AND     PITCH_HI, #3Fh                  ; clear old bits 7:6 in PITCH_HI
        OR      PITCH_HI, R12                   ; commit: merge EXSLA into PITCH_HI bits 7:6
        JR      synthesis_loop_reentry          ; back to poll loop

; ============================================================
; === SYNTHESIS OUTPUT — parameter table read ($0E62) ===
; ============================================================
        ORG     0E62h
synthesis_output:                                ; 1 refs
; synthesis_output: read param table and switch micro-op mode.
; Inputs:
;   R13 = param table index (from pitch_output, points to Synthesis output param table byte0)
;   R11 = fractional dither pattern (from pitch_output ROM[$0232+i])
;   R10 = multiply result magnitude (from R12 at pitch_output)
; ROM[$01:R13] = 3-byte entry: byte0=T (timer/freq step), byte1=micro-op, byte2=PRE0.
; 
; T byte determines which mode family the new sub belongs to:
;   T >= $40: oversampled modes (8x/4x/2x). Timer runs at T=$80.
;   T <  $40: direct 1x DDS mode ($C4). Timer runs at T=$01-$20.
; 
; UPPER PATH (T>=$40 → oversampled modes, sub 0-7):
;   Reads byte1 (new micro-op: $20/$82/$AC).
;   If reg[$1E]<$C4 (already oversampled): just update reg[$1E]. No R5 change.
;     The running chain picks up new reg[$1E] via LD R5,reg[$1E] at chain end.
;   If reg[$1E]>=$C4 (was 1x DDS): .switch_to_oversampling: DI, R14=R15=waveform[PHASE],
;     force R5 to new oversample chain. Safe transition: R14/R15 primed as samples.
; 
; LOWER PATH (T<$40 → 1x DDS, sub 8+):
;   If reg[$1E]>=$C4 (already 1x DDS): update R14=T (new freq step), update reg[$1E].
;     No R5 change needed — $C4 reloads R5 from reg[$1E] every IRQ4.
;   If reg[$1E]<$C4 (was oversampled): .switch_to_direct_sampling: DI, R14=T, force R5=$C4.
;     Chain transitions are safe: chain runs to last step before reading new reg[$1E].
;     Race only when R5=$19 (micro_init): sets R7=$40, then $C4 reads 40h($40)=CRASH.
;     See WIP_ocean_crash.md.
        AND     0FAh, #0FDh                     ; 0FA=IRQ (interrupt request)
        LD      R12, #01h                       ; R12=$01: ROM high byte for param table at $01xx
        LD      0FEh, R11                       ; 0FE=SPH (phase accumulator high)  ; save dither pattern to SPH — IRQ4 rotates SPH, carry dithers T0 ±1
        LDC     R11, @RR12                      ; byte0 = T (timer reload for oversampled / freq step for 1x DDS)
        INC     R13                             ; advance to byte1
        CP      R11, #40h                       ; T >= $40? split oversampled vs 1x DDS
        JR      C, .no_oversampling             ; T < $40 → 1x DDS path (sub 8+)
.oversampling:
        LDC     R11, @RR12                      ; byte1 = new oversample micro-op ($20/$82/$AC)
        CP      MICRO_OP_NEXT, #0C4h            ; currently in 1x DDS mode? (reg[$1E] >= $C4)
        JR      C, .synthesis_output_common     ; already oversampled → common (no R5 override); was 1x DDS → switch_to_oversampling
.switch_to_oversampling:
        DI
        LD      WAVE_R15, 40h(PHASE)            ; R15 = current waveform sample at PHASE
        LD      WAVE_R14, WAVE_R15              ; R14 = R15 (both primed for oversample chain working registers)
        LD      MICRO_OP, R11                   ; force R5 = new oversample micro-op
        JR      .synthesis_output_common
.no_oversampling:                                ; 1 refs
        CP      MICRO_OP_NEXT, #0C4h            ; T < $40: currently in 1x DDS? (reg[$1E] >= $C4)
        JR      C, .switch_to_direct_sampling   ; was oversampled → switch_to_direct_sampling; already 1x DDS → update_phase_increment
.update_phase_increment:
        LD      WAVE_R14, R11                   ; 1x DDS steady: update R14 = T = new freq step
        LDC     R11, @RR12                      ; byte1 = $C4 (same mode, new freq step only)
        JR      .synthesis_output_common        ; update reg[$1E], R5 unchanged — $C4 reloads from reg[$1E] each IRQ4
.switch_to_direct_sampling:                                ; 1 refs
        DI
        LD      WAVE_R14, R11                   ; R14 = T = freq step for 1x DDS
        LDC     R11, @RR12                      ; byte1 = $C4 (micro_1x_dds)
        LD      MICRO_OP, R11                   ; force R5=$C4 — if IRQ4 ran micro_init before DI, R7=$40 → CRASH
.synthesis_output_common:                                ; 3 refs
        LD      MICRO_OP_NEXT, R11              ; reg[$1E] = new micro-op for next IRQ4 dispatch
        EI
        INC     R13                             ; advance to byte2
        LDC     R12, @RR12                      ; byte2 = PRE0 (timer prescaler: bits 7:2 = divisor, 0=64)
        LD      0F5h, R12                       ; 0F5=PRE0 (timer 0 prescaler)  ; set timer prescaler hardware register
; Set pitch from normalized multiply result (NOT the T byte!).
; R10 = high byte of ACC * PITCH_coeff / 2048, normalized to >= $1E.
; This IS the actual pitch: timer period = R10 * prescaler * 4 ext clocks.
; IRQ4 dithers ±1 via SPH for fractional pitch (3 extra bits from R11).
        LD      TIMER_VAL, R10
        LD      TIMER_LOAD, R10                 ; TIMER_LOAD = R10. IRQ1 writes TIMER_LOAD→T0 to start timer
        TCM     0FCh, #01h                      ; 0FC=FLAGS (flags register)  ; FLAGS bit 0: 0→interpreter (normal), 1→pass_done (first pass only)
        JP      NZ, micro_program_interpreter
.synthesis_pass_done:
; synthesis_pass_done: runs ONCE at end of initial RAUD setup.
; OR IMR,#$02: enable IRQ1 (ECLK input on P3.3) — wait for COP's first ECLK.
; When COP sends the next ECLK pulse, irq1_handler fires:
;   loads T0 timer, starts T0, enables IRQ4, forces first IRQ4
;   → micro-op dispatch begins → DAC output starts.
; After this one-shot, FLAGS bit 0 is cleared → subsequent passes go
; through micro_program_interpreter instead (normal synthesis loop).
        OR      0FBh, #02h                      ; 0FB=IMR (interrupt mask)
        EI
        LD      0F8h, #0Ch                      ; 0F8=P01M (port 0/1 mode)  ; set P01M to output mode (Port 0 = DAC data, Port 1 = bus)
        XOR     PORT2, #07h                     ; toggle Port 2 bus control bits (release slave RAM bus)
        LD      0F6h, #04h                      ; 0F6=P2M (port 2 mode / RARC)  ; set P2M for RARC operation
        AND     0FCh, #0FEh                     ; 0FC=FLAGS (flags register)  ; clear FLAGS bit 0 → next synthesis_output_common goes to interpreter, not here
        LD      R11, 0FEh                       ; 0FE=SPH (phase accumulator high)  ; restore R11 = dither pattern from SPH
        SUB     R13, #02h                       ; R13 -= 2: undo the 2x INC in synthesis_output → R13 back to byte0 offset
        JP      synthesis_loop_reentry          ; → synthesis_loop_reentry: poll for ECLK, then call synthesis_output

; ============================================================
; === IRQ1 — Timer Setup (ECLK-triggered) ($0EBE) ===
; ============================================================
        ORG     0EBEh
irq1_handler:
; irq1_handler: triggered by ECLK (COP envelope clock, ~200Hz per voice).
; LD T0, TIMER_LOAD: load T0 counter with R6 (base pitch value).
; Starts timer T0 which generates IRQ4 at the sample rate.
; Only fires ONCE per ECLK cycle (disables IRQ1, enables IRQ4).
; After IRET, IRQ4 fires immediately (forced pending) → first micro-op runs.
        LD      0F4h, TIMER_LOAD                ; 0F4=T0 (timer 0 counter)
        OR      0F1h, #03h                      ; 0F1=TMR (timer mode register)  ; start T0 timer with T_OUT toggle (TMR bits 1:0 = $03)
        LD      MICRO_OP, MICRO_OP_NEXT         ; R5 = reg[$1E] — load current micro-op for IRQ4 dispatch
        AND     0FBh, #0FDh                     ; 0FB=IMR (interrupt mask)  ; disable IRQ1 (one-shot: don't re-trigger until next synthesis_pass_done)
        OR      0FBh, #10h                      ; 0FB=IMR (interrupt mask)  ; enable IRQ4 (timer T0 interrupt → micro-op dispatch at sample rate)
        OR      0FAh, #10h                      ; 0FA=IRQ (interrupt request)  ; force IRQ4 pending → first micro-op fires immediately after IRET
        IRET

; ============================================================
; === Overflow path: result > 16 bits. Halve + re-apply PITCH_ENV. Should rarely fire with correct ACC base ($0ECF) ===
; ============================================================
        ORG     0ECFh
finalize.pitch_overflow:                                ; 1 refs
        RRC     R10
        RRC     R11
        CP      PITCH_ENV, ZERO
        JP      Z, .overflow_shift_check
        CLR     R12
        CLR     R13
        RR      PITCH_ENV
        JR      NC, .L_0EE5
        ADD     R13, R11
        ADC     R12, R10
.L_0EE5:                                ; called from: finalize.pitch_overflow($0EDF)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0EF1
        ADD     R13, R11
        ADC     R12, R10
.L_0EF1:                                ; called from: .L_0EE5($0EEB)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0EFD
        ADD     R13, R11
        ADC     R12, R10
.L_0EFD:                                ; called from: .L_0EF1($0EF7)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0F09
        ADD     R13, R11
        ADC     R12, R10
.L_0F09:                                ; called from: .L_0EFD($0F03)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0F15
        ADD     R13, R11
        ADC     R12, R10
.L_0F15:                                ; called from: .L_0F09($0F0F)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .L_0F21
        ADD     R13, R11
        ADC     R12, R10
.L_0F21:                                ; called from: .L_0F15($0F1B)
        RRC     R12
        RRC     R13
        RR      PITCH_ENV
        JR      NC, .mul_exsla_bit0
        ADD     R13, R11
        ADC     R12, R10
.mul_exsla_bit0:                                ; 1 refs
        RRC     R12
        RRC     R13
        TCM     PITCH_HI, #40h
        JR      NZ, .mul_exsla_bit1
        RCF
        RRC     R12
        RRC     R13
.mul_exsla_bit1:                                ; 1 refs
        TCM     PITCH_HI, #80h
        JR      NZ, .modulation_dir_check
        RCF
        RRC     R12
        RRC     R13
        SRA     R12
        RRC     R13
.modulation_dir_check:                                ; 1 refs
        TCM     PITCH_ENV, #01h
        JR      NZ, .L_0F54
        SBC     R11, R13
        SBC     R10, R12
        JR      .overflow_shift_check
.L_0F54:                                ; called from: .modulation_dir_check($0F4C)
        ADC     R11, R13
        ADC     R12, R10
        JR      NC, .overflow_shift_check_i
        RRC     R12
        RRC     R11
        LD      R13, MODE
        AND     R13, #0Fh
        DEC     R13
        JR      PL, .overflow_shift_check_ii
        INC     R13
        JP      finalize_output.pitch_output
.overflow_shift_check:                                ; 2 refs
        LD      R12, R10
.overflow_shift_check_i:                                ; 1 refs
        LD      R13, MODE
        AND     R13, #0Fh
.overflow_shift_check_ii:                                ; 1 refs
        DEC     R13
        JP      PL, finalize_output.pitch_output
        INC     R13
        JP      finalize_output.pitch_output
finalize_output.check_underflow_ld_r12_r10:                                ; 1 refs
        LD      R12, R10
        JP      finalize_output.check_underflow
finalize_output.overflow_shift:                                ; 1 refs
        RRC     R12
        RRC     R11
        LD      R13, MODE                       ; reload sub from mode byte
        AND     R13, #0Fh
        DEC     R13                             ; DEC sub — overflow means signal is too large for current sub
        JP      PL, finalize_output.pitch_output; if sub still >= 0, use decremented sub
        INC     R13                             ; sub went negative → restore to 0
        JP      finalize_output.pitch_output

; ============================================================
; === Normalize underflow: shift R12:R11 left until R12 >= $1E ($0F92) ===
; ============================================================
        ORG     0F92h
finalize_output.underflow_shift:                                ; 2 refs
; normalize: floating-point normalization of multiply result.
; R12:R11 = mantissa (multiply result), R13 = exponent (sub mode).
; Shifts mantissa left (x2) and INC exponent until R12 >= $1E.
; Each sub INCrement selects a faster timer / simpler micro-op chain.
; R11 bits 7:5 become the fractional dither index at pitch_output
; (3 bits of sub-sample pitch precision from the normalize remainder).
; Sub caps at $0F (15). If still < $1E at cap: force R12=$1E, R11=0
; (no dither = exact pitch, enters underflow_shift_entry skipping dither lookup).
        CP      R13, #0Fh
        JR      NC, .L_0FA5                     ; sub < 15 → keep normalizing
        INC     R13                             ; INC sub (exponent++)
        RCF
        RLC     R11                             ; RLC R11:R12 = mantissa x2 (shift bits up, dither bits accumulate in R11)
        RLC     R12
        CP      R12, #1Eh                       ; R12 >= $1E? mantissa normalized → pitch_output (R11 has dither in bits 7:5)
        JP      NC, finalize_output.pitch_output
        JR      finalize_output.underflow_shift ; loop: keep shifting until normalized or capped
.L_0FA5:                                ; called from: finalize_output.underflow_shift($0F95)
        LD      R12, #1Eh                       ; cap: force R12=$1E (minimum normalized magnitude)
        CLR     R11                             ; R11=0 → SPH=$00 at synthesis_output → no timer dither (exact integer pitch)
        JP      finalize_output.pitch_output.underflow_shift_entry; → underflow_shift_entry: skip dither table lookup, R11=0 passes through to SPH
        NOP
        NOP
        NOP
        NOP
        NOP
        JP      init_full
        NOP
        NOP
        NOP
        JP      init_full
        NOP
        NOP
        NOP
        JP      init_full

; === Quarter-sine scaling LUT ===
        ORG     0FC0h
        DB      03h, 06h, 09h, 0Ch              ; [0]-[3]
        DB      10h, 13h, 16h, 19h              ; [4]-[7]
        DB      1Ch, 1Fh, 22h, 25h              ; [8]-[11]
        DB      28h, 2Bh, 2Eh, 31h              ; [12]-[15]
        DB      33h, 36h, 39h, 3Ch              ; [16]-[19]
        DB      3Fh, 41h, 44h, 47h              ; [20]-[23]
        DB      49h, 4Ch, 4Eh, 51h              ; [24]-[27]
        DB      53h, 55h, 58h, 5Ah              ; [28]-[31]
        DB      5Ch, 5Eh, 60h, 62h              ; [32]-[35]
        DB      64h, 66h, 68h, 6Ah              ; [36]-[39]
        DB      6Bh, 6Dh, 6Fh, 70h              ; [40]-[43]
        DB      71h, 73h, 74h, 75h              ; [44]-[47]
        DB      76h, 78h, 79h, 7Ah              ; [48]-[51]
        DB      7Ah, 7Bh, 7Ch, 7Dh              ; [52]-[55]
        DB      7Dh, 7Eh, 7Eh, 7Eh              ; [56]-[59]
        DB      7Fh, 7Fh, 7Fh, 7Fh              ; [60]-[63]

        END
